// Build a compact text dump of every screen into one frame name for verification
const page = figma.getNodeById("3:2");
const order = ["01_Sign_In","02_Sign_Up","03_Home","04_Search","05_Explore_Products","06_Filter","07_Product_Overview","08_Product_Features","09_Shopping_Cart","10_Profile"];
const parts = [];
function collect(node, screenName){
  const parts2 = [];
  (function walk(n, path){
    if(n.type==="TEXT"){
      let c = n.characters.replace(/\n/g,"\\n");
      if(c.length>40) c = c.slice(0,40)+"…";
      parts2.push(n.name + "=" + c);
    }
    if("children" in n){ n.children.forEach(ch=>walk(ch,path)); }
  })(node,"");
  parts.push(screenName + " :: " + parts2.join(" | "));
}
for(const nm of order){
  const f = page.children.find(c=>c.type==="FRAME" && c.name===nm);
  if(f) collect(f,nm); else parts.push(nm+" :: MISSING");
}
let dump = parts.join(" \\n ");
if(dump.length>3900) dump = dump.slice(0,3900);
// Store dump as name of a diagnostic frame
const diag = page.children.find(c=>c.name==="TEXTDUMP");
let d;
if(diag){ d=diag; } else { d=figma.createFrame(); page.appendChild(d); }
d.name = "TEXTDUMP"; d.resize(10,10);
const t = d.children[0] && d.children[0].type==="TEXT" ? d.children[0] : figma.createText();
await figma.loadFontAsync({family:"DM Sans", style:"Regular"});
t.fontName={family:"DM Sans", style:"Regular"}; t.fontSize=8;
t.characters = dump; d.appendChild(t);
"dump stored";

