const page = figma.getNodeById("3:2");
const names = ["Product Card · HD","Product Card · Cable","Promo Card · MOD-2","Promo Card · DJ","Recent Search Row · MOD-2 Wireless","Popular Product Row · Comfort","Cart Row · Comfort","Review Item · Madelina","Review Item · Irfan","Feature Row · Headband","Auth Field · Mail","Button · Sign Up"];
const lines = [];
for(const nm of names){
  const c = page.children.find(x=>x.type==="COMPONENT" && x.name===nm);
  if(!c){ lines.push(nm+" :: MISSING"); continue; }
  const parts = [];
  (function w(n, d){
    if(d>2) return;
    let tag = n.type;
    if(n.type==="INSTANCE"){ try{ tag = "I("+n.masterComponent.name+")"; }catch(e){ tag="I"; } }
    if(n.type==="TEXT"){ let ch="?"; try{ ch=n.characters; }catch(e){} tag="T("+ch+")"; }
    parts.push(n.name+"|"+tag);
    if(n.children){ n.children.forEach(c=>w(c,d+1)); }
  })(c,0);
  lines.push(nm+" :: "+parts.join(" | "));
}
