(async () => {
  const info = (id) => {
    const n = figma.getNodeById(id);
    const rec = (node, depth) => {
      const o = { name: node.name, type: node.type, id: node.id };
      if (node.type === 'TEXT') {
        o.chars = node.characters.slice(0, 40);
        o.fontSize = node.fontSize;
        o.font = node.fontName ? (node.fontName.family + ' ' + node.fontName.style) : null;
      }
      if ('fills' in node) {
        o.fills = (node.fills && node.fills.length) ? node.fills.map(f => ({ type: f.type, vis: f.visible !== false, color: f.color ? { r: +(f.color.r*255).toFixed(0), g: +(f.color.g*255).toFixed(0), b: +(f.color.b*255).toFixed(0) } : null, op: f.opacity, imageHash: f.imageHash ? 'IMG' : null })) : [];
      }
      if ('strokeWeight' in node) o.stroke = node.strokeWeight;
      if (node.type === 'RECTANGLE' || node.type === 'FRAME' || node.type === 'ELLIPSE' || node.type === 'VECTOR') {
        o.w = Math.round(node.width); o.h = Math.round(node.height);
      }
      if (node.children && node.children.length) o.children = node.children.map(c => rec(c, depth + 1));
      if (depth > 3) o.children = null;
      return o;
    };
    return n ? rec(n, 0) : 'MISSING';
  };
  throw new Error('STRUCT A ' + JSON.stringify({
    button: info('16:29'),
    textfield: info('16:31'),
    photoHope: info('16:74'),
    iconRight: info('16:45')
  }));
})();

